const int BATTERY_PIN = A0;
const int GREEN = 4, YELLOW = 5, RED = 6;

void setup() {
  pinMode(GREEN, OUTPUT);
  pinMode(YELLOW, OUTPUT);
  pinMode(RED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  float volts = analogRead(BATTERY_PIN) * 5.0 / 1023.0;

  digitalWrite(GREEN, LOW);
  digitalWrite(YELLOW, LOW);
  digitalWrite(RED, LOW);

  Serial.print("Battery: ");
  Serial.print(volts, 2);
  Serial.print(" V  ");

  if (volts < 0.1) {
    Serial.println("(no battery)");
  } else if (volts >= 1.4) {
    digitalWrite(GREEN, HIGH);
    Serial.println("good");
  } else if (volts >= 1.2) {
    digitalWrite(YELLOW, HIGH);
    Serial.println("ok");
  } else {
    digitalWrite(RED, HIGH);
    Serial.println("dead, recycle it");
  }
  delay(500);
}

const int SENSOR_PIN = A0;
const int PUMP_RELAY = 7;
const int DRY_LEVEL = 700;           // higher number = drier soil (check yours)
const unsigned long PUMP_MS = 3000;  // water for 3 seconds
const unsigned long SOAK_MS = 60000; // then wait a minute for it to soak in

void setup() {
  pinMode(PUMP_RELAY, OUTPUT);
  digitalWrite(PUMP_RELAY, LOW);
  Serial.begin(9600);
}

void loop() {
  int reading = analogRead(SENSOR_PIN);
  Serial.print("Soil reading: ");
  Serial.println(reading);

  if (reading > DRY_LEVEL) {
    Serial.println("Too dry! Pumping water...");
    digitalWrite(PUMP_RELAY, HIGH);
    delay(PUMP_MS);
    digitalWrite(PUMP_RELAY, LOW);
    Serial.println("Done. Waiting for the water to soak in.");
    delay(SOAK_MS);  // stops it flooding the pot before the sensor notices
  } else {
    delay(5000);
  }
}

// How long the LED stays on (and off), in milliseconds.
const unsigned long BLINK_TIME = 1000;

void setup() {
  // Tell the board this pin is an output (it sends power out).
  pinMode(LED_BUILTIN, OUTPUT);
}

void loop() {
  digitalWrite(LED_BUILTIN, HIGH);  // LED on
  delay(BLINK_TIME);                // wait 1 second
  digitalWrite(LED_BUILTIN, LOW);   // LED off
  delay(BLINK_TIME);                // wait 1 second
}

const int BUTTON_PIN = 2;
const int LED_PIN = LED_BUILTIN;
const unsigned long DEBOUNCE_MS = 50;  // ignore wobbles shorter than this

bool ledOn = false;
int lastReading = HIGH;          // what the pin said last time
int stableState = HIGH;          // the "real" button state after debounce
unsigned long lastChangeTime = 0;

void setup() {
  // INPUT_PULLUP keeps the pin HIGH until the button connects it to GND.
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int reading = digitalRead(BUTTON_PIN);

  // The reading changed, so restart the debounce timer.
  if (reading != lastReading) {
    lastChangeTime = millis();
  }

  // It stayed the same long enough, so trust it.
  if (millis() - lastChangeTime > DEBOUNCE_MS && reading != stableState) {
    stableState = reading;

    // LOW means pressed (the pin is pulled to GND).
    if (stableState == LOW) {
      ledOn = !ledOn;
      digitalWrite(LED_PIN, ledOn ? HIGH : LOW);
      Serial.println(ledOn ? "LED ON" : "LED OFF");
    }
  }

  lastReading = reading;
}

const int BUZZER_PIN = 8;

// Note pitches in Hz (0 means a rest).
const int NOTE_C = 262, NOTE_D = 294, NOTE_E = 330, NOTE_F = 349, NOTE_G = 392, NOTE_A = 440;

const int melody[] = {
  NOTE_C, NOTE_C, NOTE_G, NOTE_G, NOTE_A, NOTE_A, NOTE_G, 0,
  NOTE_F, NOTE_F, NOTE_E, NOTE_E, NOTE_D, NOTE_D, NOTE_C, 0
};

// How long each note lasts: 4 = quarter note, 2 = half note.
const int beats[] = {
  4, 4, 4, 4, 4, 4, 2, 4,
  4, 4, 4, 4, 4, 4, 2, 4
};

const int NOTE_COUNT = sizeof(melody) / sizeof(melody[0]);
const int WHOLE_NOTE_MS = 1600;  // smaller = faster song

void setup() {
  pinMode(BUZZER_PIN, OUTPUT);
}

void loop() {
  for (int i = 0; i < NOTE_COUNT; i++) {
    int noteLength = WHOLE_NOTE_MS / beats[i];

    if (melody[i] > 0) {
      tone(BUZZER_PIN, melody[i], noteLength);
    }

    // Wait a little longer than the note so notes don't blur together.
    delay(noteLength * 13 / 10);
    noTone(BUZZER_PIN);
  }

  delay(2000);  // pause before playing again
}

const int S0 = 4, S1 = 5, S2 = 6, S3 = 7, OUT_PIN = 8;

// The sensor sends pulses. A SHORTER pulse means MORE of that color.
unsigned long readColor(int s2, int s3) {
  digitalWrite(S2, s2);
  digitalWrite(S3, s3);
  delay(20);
  return pulseIn(OUT_PIN, LOW, 50000UL);
}

void setup() {
  pinMode(S0, OUTPUT);
  pinMode(S1, OUTPUT);
  pinMode(S2, OUTPUT);
  pinMode(S3, OUTPUT);
  pinMode(OUT_PIN, INPUT);
  digitalWrite(S0, HIGH);  // S0 high + S1 low = 20% speed, good for Arduino
  digitalWrite(S1, LOW);
  Serial.begin(9600);
}

void loop() {
  unsigned long red = readColor(LOW, LOW);
  unsigned long blue = readColor(LOW, HIGH);
  unsigned long green = readColor(HIGH, HIGH);

  Serial.print("R: ");
  Serial.print(red);
  Serial.print("  G: ");
  Serial.print(green);
  Serial.print("  B: ");
  Serial.print(blue);
  Serial.print("  -> ");

  // The smallest number is the strongest color.
  if (red < green && red < blue) Serial.println("RED");
  else if (green < red && green < blue) Serial.println("GREEN");
  else if (blue < red && blue < green) Serial.println("BLUE");
  else Serial.println("not sure");
  delay(500);
}

#include <IRremote.hpp>

const int IR_PIN = 11;
const int LED_PINS[] = {4, 5, 6};

// These are the codes for the common little "Car MP3" style remote.
const uint16_t BUTTON_0 = 0x16;
const uint16_t BUTTON_1 = 0x0C;
const uint16_t BUTTON_2 = 0x18;
const uint16_t BUTTON_3 = 0x5E;

bool ledOn[3] = {false, false, false};

void toggle(int which) {
  ledOn[which] = !ledOn[which];
  digitalWrite(LED_PINS[which], ledOn[which] ? HIGH : LOW);
}

void setup() {
  for (int i = 0; i < 3; i++) pinMode(LED_PINS[i], OUTPUT);
  IrReceiver.begin(IR_PIN);
}

void loop() {
  if (!IrReceiver.decode()) return;  // nothing pressed yet

  bool isRepeat = IrReceiver.decodedIRData.flags & IRDATA_FLAGS_IS_REPEAT;
  uint16_t code = IrReceiver.decodedIRData.command;
  IrReceiver.resume();
  if (isRepeat) return;

  switch (code) {
    case BUTTON_1: toggle(0); break;
    case BUTTON_2: toggle(1); break;
    case BUTTON_3: toggle(2); break;
    case BUTTON_0:
      for (int i = 0; i < 3; i++) {
        ledOn[i] = false;
        digitalWrite(LED_PINS[i], LOW);
      }
      break;
  }
}

// Tip: pull the little jumper off the L298N's ENA pins so the Arduino can set the speed.
const int ENA_PIN = 9;  // speed pin (must be a ~PWM pin)
const int IN1_PIN = 8;  // direction pin 1
const int IN2_PIN = 7;  // direction pin 2

void setup() {
  pinMode(ENA_PIN, OUTPUT);
  pinMode(IN1_PIN, OUTPUT);
  pinMode(IN2_PIN, OUTPUT);
  Serial.begin(9600);
}

// Set the direction: true = forward, false = backward.
void setDirection(bool forward) {
  digitalWrite(IN1_PIN, forward ? HIGH : LOW);
  digitalWrite(IN2_PIN, forward ? LOW : HIGH);
}

// Stop the motor.
void stopMotor() {
  digitalWrite(IN1_PIN, LOW);
  digitalWrite(IN2_PIN, LOW);
  analogWrite(ENA_PIN, 0);
}

// Speed up from slow to full, then slow back down.
void rampSpeed() {
  for (int speed = 80; speed <= 255; speed += 5) {
    analogWrite(ENA_PIN, speed);
    delay(30);
  }
  for (int speed = 255; speed >= 80; speed -= 5) {
    analogWrite(ENA_PIN, speed);
    delay(30);
  }
}

void loop() {
  Serial.println("Forward");
  setDirection(true);
  rampSpeed();

  stopMotor();
  delay(1000);

  Serial.println("Backward");
  setDirection(false);
  rampSpeed();

  stopMotor();
  delay(1000);
}

#include <DHT.h>

const int DHT_PIN = 2;
DHT dht(DHT_PIN, DHT11);  // change DHT11 to DHT22 if you have the white one

void setup() {
  Serial.begin(9600);
  dht.begin();
  Serial.println("DHT11 ready!");
}

void loop() {
  // The DHT11 is slow: only read it every 2 seconds.
  delay(2000);

  float humidity = dht.readHumidity();
  float tempC = dht.readTemperature();      // Celsius
  float tempF = dht.readTemperature(true);  // true means Fahrenheit

  // isnan means "is not a number". It happens if a wire is loose.
  if (isnan(humidity) || isnan(tempC) || isnan(tempF)) {
    Serial.println("Could not read the sensor. Check the wires!");
    return;
  }

  Serial.print("Temperature: ");
  Serial.print(tempC, 1);
  Serial.print(" C / ");
  Serial.print(tempF, 1);
  Serial.print(" F   Humidity: ");
  Serial.print(humidity, 0);
  Serial.println(" %");
}

#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <DHT.h>

DHT dht(2, DHT22);
// 0x27 is the usual address. Some screens use 0x3F instead.
LiquidCrystal_I2C lcd(0x27, 16, 2);

// A little degree symbol drawn with 5x8 dots.
byte degreeSymbol[8] = {0b00110, 0b01001, 0b01001, 0b00110, 0, 0, 0, 0};

void setup() {
  dht.begin();
  lcd.init();
  lcd.backlight();
  lcd.createChar(0, degreeSymbol);
  lcd.setCursor(0, 0);
  lcd.print("Weather station");
  delay(1500);
}

void loop() {
  float humidity = dht.readHumidity();
  float tempC = dht.readTemperature();

  lcd.clear();
  if (isnan(humidity) || isnan(tempC)) {
    lcd.print("Sensor error!");
  } else {
    lcd.setCursor(0, 0);
    lcd.print("Temp: ");
    lcd.print(tempC, 1);
    lcd.write(byte(0));  // our custom degree symbol
    lcd.print("C");

    lcd.setCursor(0, 1);
    lcd.print("Humidity: ");
    lcd.print(humidity, 0);
    lcd.print("%");
  }
  delay(2000);  // the DHT22 likes 2 seconds between reads
}

const int TRIG_PIN = A0;  // analog pins work as normal digital pins too
const int ECHO_PIN = A1;
const int LED_PINS[] = {2, 3, 4, 5, 6, 7};
const int LED_COUNT = 6;
const int MAX_CM = 60;  // farther than this = no LEDs

long readDistanceCm() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  unsigned long duration = pulseIn(ECHO_PIN, HIGH, 30000UL);
  if (duration == 0) return MAX_CM;
  return duration / 58;
}

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  for (int i = 0; i < LED_COUNT; i++) {
    pinMode(LED_PINS[i], OUTPUT);
  }
}

void loop() {
  long cm = constrain(readDistanceCm(), 0, MAX_CM);
  // 0 cm -> 6 LEDs, MAX_CM -> 0 LEDs.
  int lit = map(cm, 0, MAX_CM, LED_COUNT, 0);

  for (int i = 0; i < LED_COUNT; i++) {
    digitalWrite(LED_PINS[i], i < lit ? HIGH : LOW);
  }
  delay(60);
}

const int REED_PIN = 2;
const int BUZZER_PIN = 8;
const unsigned long OPEN_TOO_LONG = 10000;

bool wasOpen = false;
unsigned long openedAt = 0;

void setup() {
  pinMode(REED_PIN, INPUT_PULLUP);  // magnet near = switch closed = LOW
  pinMode(BUZZER_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  bool open = digitalRead(REED_PIN) == HIGH;

  if (open && !wasOpen) {
    openedAt = millis();
    Serial.println("Door opened!");
    tone(BUZZER_PIN, 1800, 100);  // a quick chime
  }
  if (!open && wasOpen) {
    Serial.println("Door closed.");
    noTone(BUZZER_PIN);
  }

  if (open && millis() - openedAt > OPEN_TOO_LONG) {
    tone(BUZZER_PIN, 900, 200);  // nag beep
    delay(400);
  }

  wasOpen = open;
  delay(30);
}

const int SOUND_PIN = 2;
const int LIGHT_PIN = 9;

unsigned long firstClapTime = 0;
int claps = 0;
bool lightOn = false;

void setup() {
  pinMode(SOUND_PIN, INPUT);
  pinMode(LIGHT_PIN, OUTPUT);
}

void loop() {
  if (digitalRead(SOUND_PIN) == HIGH) {
    unsigned long now = millis();
    if (claps == 0) {
      claps = 1;
      firstClapTime = now;
    } else if (now - firstClapTime > 150) {  // ignore the echo of the same clap
      claps = 2;
    }
    delay(80);  // wait for the clap sound to finish
  }

  // Two claps inside 800 ms: flip the light.
  if (claps == 2) {
    lightOn = !lightOn;
    digitalWrite(LIGHT_PIN, lightOn ? HIGH : LOW);
    claps = 0;
    delay(300);
  }

  // Too slow? Forget the first clap.
  if (claps == 1 && millis() - firstClapTime > 800) {
    claps = 0;
  }
}

#include <OneWire.h>
#include <DallasTemperature.h>

OneWire oneWire(4);               // the data wire is on pin 4
DallasTemperature sensors(&oneWire);

void setup() {
  Serial.begin(9600);
  sensors.begin();
  Serial.print("Probes found: ");
  Serial.println(sensors.getDeviceCount());
}

void loop() {
  sensors.requestTemperatures();          // ask every probe to measure
  float tempC = sensors.getTempCByIndex(0);  // 0 = the first probe

  if (tempC == DEVICE_DISCONNECTED_C) {
    Serial.println("Probe not connected!");
  } else {
    Serial.print("Temperature: ");
    Serial.print(tempC, 2);
    Serial.print(" C  (");
    Serial.print(tempC * 9.0 / 5.0 + 32.0, 1);
    Serial.println(" F)");
  }
  delay(1000);
}

#include <DHT.h>

DHT dht(2, DHT22);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  delay(2500);
  float humidity = dht.readHumidity();
  float tempC = dht.readTemperature();
  if (isnan(humidity) || isnan(tempC)) {
    Serial.println("Sensor error");
    return;
  }

  // false = we give it Celsius and want Celsius back.
  float feelsLike = dht.computeHeatIndex(tempC, humidity, false);

  Serial.print("Real: ");
  Serial.print(tempC, 1);
  Serial.print(" C  Humidity: ");
  Serial.print(humidity, 0);
  Serial.print("%  Feels like: ");
  Serial.print(feelsLike, 1);
  Serial.print(" C  -> ");

  if (feelsLike < 18) Serial.println("Chilly, grab a hoodie.");
  else if (feelsLike < 27) Serial.println("Comfy!");
  else if (feelsLike < 32) Serial.println("Warm, drink some water.");
  else Serial.println("Very hot! Stay in the shade.");
}

#include <IRremote.hpp>

const int IR_PIN = 11;

void setup() {
  Serial.begin(9600);
  // ENABLE_LED_FEEDBACK makes the built-in LED flicker when a signal arrives.
  IrReceiver.begin(IR_PIN, ENABLE_LED_FEEDBACK);
  Serial.println("Point a remote at the sensor and press buttons.");
}

void loop() {
  if (IrReceiver.decode()) {
    // A held button sends "repeat" messages; skip those.
    if (!(IrReceiver.decodedIRData.flags & IRDATA_FLAGS_IS_REPEAT)) {
      Serial.print("Button code: 0x");
      Serial.print(IrReceiver.decodedIRData.command, HEX);
      Serial.print("   (");
      Serial.print(IrReceiver.decodedIRData.command);
      Serial.println(" in normal numbers)");
    }
    IrReceiver.resume();  // get ready for the next button
  }
}

const int FLAME_DIGITAL = 2;
const int FLAME_ANALOG = A0;
const int BUZZER_PIN = 8;
const int LED_PIN = 13;

void setup() {
  pinMode(FLAME_DIGITAL, INPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  // Most flame modules output LOW when they see a flame.
  bool fire = digitalRead(FLAME_DIGITAL) == LOW;
  int strength = 1023 - analogRead(FLAME_ANALOG);  // flip so bigger = stronger flame

  Serial.print("Flame strength: ");
  Serial.println(strength);

  if (fire) {
    digitalWrite(LED_PIN, HIGH);
    tone(BUZZER_PIN, 3000, 100);
    delay(150);
    digitalWrite(LED_PIN, LOW);
    delay(100);
  } else {
    digitalWrite(LED_PIN, LOW);
    delay(250);
  }
}

const int FSR_PIN = A0;
const int LED_PIN = 9;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int pressure = analogRead(FSR_PIN);
  analogWrite(LED_PIN, map(pressure, 0, 1023, 0, 255));

  Serial.print("Pressure: ");
  Serial.print(pressure);
  if (pressure < 10) Serial.println("  no touch");
  else if (pressure < 200) Serial.println("  light touch");
  else if (pressure < 500) Serial.println("  light squeeze");
  else if (pressure < 800) Serial.println("  medium squeeze");
  else Serial.println("  BIG squeeze!");
  delay(200);
}

#include <Wire.h>

void setup() {
  Wire.begin();
  Serial.begin(9600);
}

void loop() {
  Serial.println("Scanning...");
  int found = 0;

  for (int address = 1; address < 127; address++) {
    // Knock on each address. 0 means somebody answered.
    Wire.beginTransmission(address);
    byte result = Wire.endTransmission();
    if (result == 0) {
      Serial.print("Found a device at 0x");
      if (address < 16) Serial.print("0");
      Serial.println(address, HEX);
      found++;
    }
  }

  if (found == 0) Serial.println("Nothing found. Check the SDA and SCL wires.");
  else Serial.println("Done.");
  delay(5000);
}

#include <Keypad.h>
#include <Servo.h>

const byte ROWS = 4;
const byte COLS = 4;
char keys[ROWS][COLS] = {
  {'1', '2', '3', 'A'}, {'4', '5', '6', 'B'}, {'7', '8', '9', 'C'}, {'*', '0', '#', 'D'}
};
byte rowPins[ROWS] = {9, 8, 7, 6};
byte colPins[COLS] = {5, 4, 3, 2};
Keypad keypad = Keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);

Servo lock;
const int BUZZER_PIN = A0;
const char SECRET[] = "1234";  // change me!
char typed[9];                 // up to 8 keys plus the end marker
byte typedCount = 0;

void setup() {
  lock.attach(10);
  lock.write(0);
  pinMode(BUZZER_PIN, OUTPUT);
  Serial.begin(9600);
  Serial.println("Type the code, then press #. Press * to clear.");
}

void loop() {
  char key = keypad.getKey();
  if (key == NO_KEY) return;
  tone(BUZZER_PIN, 1500, 40);  // little click for every key

  if (key == '*') {
    typedCount = 0;
    Serial.println("Cleared");
  } else if (key == '#') {
    typed[typedCount] = '\0';  // finish the text
    if (strcmp(typed, SECRET) == 0) {
      Serial.println("Correct! Unlocked for 5 seconds.");
      lock.write(90);
      delay(5000);
      lock.write(0);
    } else {
      Serial.println("Wrong code!");
      tone(BUZZER_PIN, 200, 800);
    }
    typedCount = 0;
  } else if (typedCount < 8) {
    typed[typedCount++] = key;
    Serial.print('*');  // show stars, not the real keys
  }
}

const int LASER_PIN = 7;
const int SENSOR_PIN = A0;
const int BUZZER_PIN = 8;
const int RESET_PIN = 2;

int threshold = 0;
bool alarm = false;

void setup() {
  pinMode(LASER_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(RESET_PIN, INPUT_PULLUP);
  Serial.begin(9600);

  digitalWrite(LASER_PIN, HIGH);
  delay(500);
  // Learn how bright the laser is, then trip at 70% of that.
  int laserLevel = analogRead(SENSOR_PIN);
  threshold = laserLevel * 7 / 10;
  Serial.print("Laser level ");
  Serial.print(laserLevel);
  Serial.print(", alarm below ");
  Serial.println(threshold);
}

void loop() {
  if (!alarm && analogRead(SENSOR_PIN) < threshold) {
    alarm = true;
    Serial.println("BEAM BROKEN! Press the button to reset.");
  }

  if (alarm) {
    tone(BUZZER_PIN, 1500, 150);
    delay(300);
    if (digitalRead(RESET_PIN) == LOW) {
      alarm = false;
      noTone(BUZZER_PIN);
      Serial.println("Alarm reset.");
      delay(500);
    }
  }
}

const int POT_PIN = A0;
const int LED_PIN = 9;  // PWM pin (has a ~ next to it)

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  int knob = analogRead(POT_PIN);  // 0 to 1023
  // analogWrite only goes up to 255, so divide by 4.
  int brightness = knob / 4;
  analogWrite(LED_PIN, brightness);
  delay(10);
}

const int LIGHT_PIN = A0;
const int LED_PIN = 9;  // must be a ~ pin: 3, 5, 6, 9, 10 or 11 on an Uno

float smoothLight = 512;  // a running average stops flicker

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  int raw = analogRead(LIGHT_PIN);
  // Move 10% of the way toward the new reading each time.
  smoothLight = smoothLight * 0.9 + raw * 0.1;

  // Bright room (1023) -> LED off (0). Dark room (0) -> LED full (255).
  int brightness = map((int)smoothLight, 0, 1023, 255, 0);
  brightness = constrain(brightness, 0, 255);
  analogWrite(LED_PIN, brightness);
  delay(20);
}

const int LIGHT_PIN = A0;

void setup() {
  Serial.begin(9600);
}

void loop() {
  int light = analogRead(LIGHT_PIN);  // 0 (dark) to 1023 (bright)
  int bars = map(light, 0, 1023, 0, 40);

  Serial.print(light);
  Serial.print("\t|");
  for (int i = 0; i < 40; i++) {
    Serial.print(i < bars ? '#' : ' ');
  }
  Serial.print("| ");

  if (light < 200) Serial.println("dark");
  else if (light < 600) Serial.println("dim");
  else Serial.println("bright");

  delay(200);
}

const int HALL_PIN = 2;
const int LED_PIN = 13;
bool wasNear = false;

void setup() {
  pinMode(HALL_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  // The A3144 pulls its pin LOW when it feels a magnet's south pole.
  bool near = digitalRead(HALL_PIN) == LOW;
  digitalWrite(LED_PIN, near ? HIGH : LOW);

  if (near && !wasNear) Serial.println("Magnet arrived!");
  if (!near && wasNear) Serial.println("Magnet gone.");
  wasNear = near;
  delay(20);
}

const int PIR_PIN = 2;
const int LIGHT_PIN = 9;
const unsigned long STAY_ON_MS = 20000;  // 20 seconds

unsigned long lastMotionTime = 0;
bool lightOn = false;

void setup() {
  pinMode(PIR_PIN, INPUT);
  pinMode(LIGHT_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  // Every time we see motion, restart the timer.
  if (digitalRead(PIR_PIN) == HIGH) {
    lastMotionTime = millis();
    if (!lightOn) {
      lightOn = true;
      digitalWrite(LIGHT_PIN, HIGH);
      Serial.println("Light ON");
    }
  }

  // millis() - start is the safe way to measure time, even when millis wraps around.
  if (lightOn && millis() - lastMotionTime >= STAY_ON_MS) {
    lightOn = false;
    digitalWrite(LIGHT_PIN, LOW);
    Serial.println("No motion for a while, light off");
  }
}

