// Turns a joystick reading into a speed from -3 to 3, with a dead zone in the middle.
int stickSpeed(int reading) {
  int offset = reading - 512;
  if (abs(offset) < 80) return 0;
  return map(offset, -512, 511, -3, 3);
}

