const int SENSOR_PIN = A0;
const int SAMPLES = 10;

int readings[SAMPLES];  // a ring of the last 10 readings
int slot = 0;
long total = 0;

void setup() {
  Serial.begin(9600);
  for (int i = 0; i < SAMPLES; i++) readings[i] = 0;
}

void loop() {
  int raw = analogRead(SENSOR_PIN);

  // Take the oldest reading out of the total and put the new one in.
  total -= readings[slot];
  readings[slot] = raw;
  total += raw;
  slot = (slot + 1) % SAMPLES;

  int average = total / SAMPLES;

  // "Label:value" lines give the Serial Plotter named lines.
  Serial.print("raw:");
  Serial.print(raw);
  Serial.print(",smooth:");
  Serial.println(average);
  delay(20);
}

const int MIC_PIN = A0;
const int LED_PINS[] = {3, 4, 5, 6, 7};
const int LED_COUNT = 5;

void setup() {
  for (int i = 0; i < LED_COUNT; i++) pinMode(LED_PINS[i], OUTPUT);
  Serial.begin(9600);
}

void loop() {
  // Sound is a wave, so we measure how far it swings in 50 ms.
  int highest = 0;
  int lowest = 1023;
  unsigned long start = millis();
  while (millis() - start < 50) {
    int sample = analogRead(MIC_PIN);
    if (sample > highest) highest = sample;
    if (sample < lowest) lowest = sample;
  }
  int loudness = highest - lowest;  // bigger swing = louder

  // Change 200 if your sensor is more or less sensitive.
  int lit = map(constrain(loudness, 0, 200), 0, 200, 0, LED_COUNT);
  for (int i = 0; i < LED_COUNT; i++) {
    digitalWrite(LED_PINS[i], i < lit ? HIGH : LOW);
  }
  Serial.println(loudness);
}

