const int TOUCH_PIN = 2;
const int LED_PIN = 9;
const int LEVELS[] = {0, 30, 110, 255};  // off, dim, medium, bright
int level = 0;
int lastTouch = LOW;

void setup() {
  pinMode(TOUCH_PIN, INPUT);
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  int touch = digitalRead(TOUCH_PIN);  // HIGH while a finger is on it

  if (touch == HIGH && lastTouch == LOW) {  // a new tap
    level = (level + 1) % 4;                // 0,1,2,3 then back to 0
    analogWrite(LED_PIN, LEVELS[level]);
  }
  lastTouch = touch;
  delay(30);
}

const int RED_PIN = 12;
const int YELLOW_PIN = 11;
const int GREEN_PIN = 10;

// Turn on just one light and turn the others off.
void showLight(int pinToTurnOn) {
  digitalWrite(RED_PIN, pinToTurnOn == RED_PIN ? HIGH : LOW);
  digitalWrite(YELLOW_PIN, pinToTurnOn == YELLOW_PIN ? HIGH : LOW);
  digitalWrite(GREEN_PIN, pinToTurnOn == GREEN_PIN ? HIGH : LOW);
}

void setup() {
  pinMode(RED_PIN, OUTPUT);
  pinMode(YELLOW_PIN, OUTPUT);
  pinMode(GREEN_PIN, OUTPUT);
}

void loop() {
  showLight(GREEN_PIN);
  delay(5000);  // go for 5 seconds

  showLight(YELLOW_PIN);
  delay(2000);  // slow down for 2 seconds

  showLight(RED_PIN);
  delay(5000);  // stop for 5 seconds
}

const int TRIG_PIN = 9;
const int ECHO_PIN = 10;

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  Serial.begin(9600);
}

void loop() {
  // Send a tiny 10 microsecond "ping".
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  // Time how long the echo takes to come back (give up after 30 ms).
  unsigned long duration = pulseIn(ECHO_PIN, HIGH, 30000UL);

  if (duration == 0) {
    Serial.println("Nothing in range");
  } else {
    // Sound goes about 0.0343 cm per microsecond, there and back, so divide by 2.
    float distanceCm = duration * 0.0343 / 2.0;
    Serial.print("Distance: ");
    Serial.print(distanceCm, 1);
    Serial.println(" cm");
  }

  delay(200);
}

#include <Servo.h>

Servo radarServo;
const int TRIG_PIN = 9;
const int ECHO_PIN = 10;

int readDistanceCm() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  unsigned long duration = pulseIn(ECHO_PIN, HIGH, 25000UL);
  if (duration == 0) return 0;  // 0 means "nothing seen"
  return duration / 58;
}

void scanAt(int angle) {
  radarServo.write(angle);
  delay(30);  // let the servo get there
  int cm = readDistanceCm();
  Serial.print("Angle ");
  Serial.print(angle);
  Serial.print(" : ");
  if (cm == 0) {
    Serial.println("clear");
  } else {
    Serial.print(cm);
    Serial.print(" cm");
    if (cm < 30) Serial.print("  <-- OBJECT CLOSE!");
    Serial.println();
  }
}

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  radarServo.attach(11);
  Serial.begin(9600);
}

void loop() {
  for (int angle = 15; angle <= 165; angle += 3) scanAt(angle);  // sweep right
  for (int angle = 165; angle >= 15; angle -= 3) scanAt(angle);  // and back
}

#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);
const int TRIG_PIN = 9;
const int ECHO_PIN = 10;

float readDistanceCm() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  unsigned long duration = pulseIn(ECHO_PIN, HIGH, 30000UL);
  if (duration == 0) return -1;      // no echo came back
  return duration * 0.0343 / 2.0;    // speed of sound is 0.0343 cm per microsecond
}

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  lcd.init();
  lcd.backlight();
}

void loop() {
  float cm = readDistanceCm();
  lcd.clear();
  lcd.setCursor(0, 0);
  if (cm < 0) {
    lcd.print("Out of range");
  } else {
    lcd.print("Dist: ");
    lcd.print(cm, 1);
    lcd.print(" cm");
    lcd.setCursor(0, 1);
    lcd.print("      ");
    lcd.print(cm / 2.54, 1);
    lcd.print(" in");
  }
  delay(300);
}

