  digitalWrite(SENSOR_POWER, LOW);
  Serial.begin(9600);
}

int readLevel() {
  digitalWrite(SENSOR_POWER, HIGH);  // only power it while reading so it rusts slower
  delay(10);
  int value = analogRead(SENSOR_PIN);
  digitalWrite(SENSOR_POWER, LOW);
  return value;
}

void loop() {
  int level = readLevel();
  Serial.print("Water level: ");
  Serial.print(level);

