    Serial.println("  (dry)");
  } else if (level < 400) {
    Serial.println("  (low)");
  } else if (level < 550) {
    Serial.println("  (medium)");
  } else {
    Serial.println("  (HIGH! overflow warning)");
    tone(BUZZER_PIN, 2500, 300);
  }
  delay(1000);
}

#include <iostream>
#include <string>

// A class is a blueprint. Each Pet we make from it is an "object".
class Pet {
public:
  // The constructor runs when a new Pet is made.
  Pet(const std::string &name, const std::string &species)
      : name_(name), species_(species) {}

  void feed() {
    hunger_ = clamp(hunger_ - 30);
    std::cout << name_ << " munches some food. Yum!\n";
  }

  void play() {
    happiness_ = clamp(happiness_ + 20);
    hunger_ = clamp(hunger_ + 10);  // playing makes you hungry
    std::cout << name_ << " plays fetch!\n";
  }

  void showStatus() const {
    std::cout << name_ << " the " << species_ << " - hunger: " << hunger_
              << "/100, happiness: " << happiness_ << "/100";
    if (hunger_ > 70) std::cout << " (very hungry!)";
    std::cout << "\n";
  }

  const std::string &getName() const { return name_; }

private:
  // Private data: only the Pet's own functions can change it.
  std::string name_;
  std::string species_;
  int hunger_ = 50;
  int happiness_ = 50;

  // Keep a value between 0 and 100.
  static int clamp(int value) {
    if (value < 0) return 0;
    if (value > 100) return 100;
    return value;
  }
};

int main() {
  // Two different objects made from the same class.
  Pet dog("Biscuit", "dog");
  Pet cat("Pixel", "cat");

  dog.showStatus();
  cat.showStatus();
  std::cout << "\n";

  dog.play();
  dog.play();
  cat.feed();
  std::cout << "\n";

  dog.showStatus();
  cat.showStatus();

  std::cout << "\nRemember to feed " << dog.getName() << " soon!\n";
  return 0;
}

#include <chrono>
#include <iostream>
#include <sstream>
#include <string>
#include <thread>

int main() {
  int seconds = 0;
  std::string line;

  // Keep asking until we get a number from 1 to 3600.
  while (true) {
    std::cout << "Count down from how many seconds? (1-3600): ";
    if (!std::getline(std::cin, line)) return 0;  // input closed
    std::istringstream in(line);
    char extra;
    if (in >> seconds && !(in >> extra) && seconds >= 1 && seconds <= 3600) break;
    std::cout << "Please type a whole number from 1 to 3600.\n";
  }

  // Remember when we started.
  auto start = std::chrono::steady_clock::now();

  for (int left = seconds; left > 0; left--) {
    int minutes = left / 60;
    int secs = left % 60;
    // \r jumps back to the start of the line so the number updates in place.
    std::cout << "\r" << minutes << ":" << (secs < 10 ? "0" : "") << secs << "   " << std::flush;
    std::this_thread::sleep_for(std::chrono::seconds(1));
  }

  auto end = std::chrono::steady_clock::now();
  auto tookMs = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();

  std::cout << "\r0:00   \nTime's up! Beep beep beep!\n";
  std::cout << "That really took " << tookMs / 1000.0 << " seconds.\n";
  return 0;
}

#include <algorithm>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

// A struct groups related data together.
struct Score {
  std::string name;
  int points;
};

void printTop(const std::vector<Score> &scores, std::size_t howMany) {
  std::cout << "\n=== HIGH SCORES ===\n";
  for (std::size_t i = 0; i < scores.size() && i < howMany; i++) {
    std::cout << (i + 1) << ". " << scores[i].name << " - " << scores[i].points << "\n";
  }
}

int main() {
  std::vector<Score> scores = {
      {"Ava", 1200}, {"Leo", 950}, {"Mia", 1500}, {"Sam", 700}, {"Zoe", 1100}};

  // Ask for the player's name.
  std::cout << "Your name: ";
  std::string name;
  if (!std::getline(std::cin, name)) return 0;
  if (name.empty()) name = "Player";

  // Ask for a score until it's a real number.
  int points = 0;
  while (true) {
    std::cout << "Your score: ";
    std::string line;
    if (!std::getline(std::cin, line)) return 0;
    std::istringstream in(line);
    char extra;
    if (in >> points && !(in >> extra) && points >= 0) break;
    std::cout << "Please type a whole number (0 or more).\n";
  }
  scores.push_back({name, points});

  // Sort biggest first. The little function says how to compare two scores.
  std::sort(scores.begin(), scores.end(), [](const Score &a, const Score &b) {
    return a.points > b.points;
  });

  printTop(scores, 5);

  // Find where the player ended up.
  for (std::size_t i = 0; i < scores.size(); i++) {
    if (scores[i].name == name && scores[i].points == points) {
      std::cout << "\nYou placed #" << (i + 1) << "!";
      if (i < 5) std::cout << " You made the top 5!";
      std::cout << "\n";
      break;
    }
  }
  return 0;
}

#include <iostream>

int main() {
  // The classic first program.
  std::cout << "Hello, world!\n\n";

  // A for loop: start at 1, keep going while i <= 5, add 1 each time.
  std::cout << "Counting up: ";
  for (int i = 1; i <= 5; i++) {
    std::cout << i << " ";
  }
  std::cout << "\n";

  // A while loop: keep going while the condition is true.
  std::cout << "Doubling: ";
  int number = 1;
  while (number < 200) {
    std::cout << number << " ";
    number *= 2;
  }
  std::cout << "\n\n";

  // If / else if / else with FizzBuzz:
  // multiples of 3 say Fizz, of 5 say Buzz, of both say FizzBuzz.
  for (int i = 1; i <= 20; i++) {
    if (i % 15 == 0) {
      std::cout << "FizzBuzz\n";
    } else if (i % 3 == 0) {
      std::cout << "Fizz\n";
    } else if (i % 5 == 0) {
      std::cout << "Buzz\n";
    } else {
      std::cout << i << "\n";
    }
  }

  // A loop inside a loop makes a times table.
  std::cout << "\nTimes table:\n";
  for (int row = 1; row <= 5; row++) {
    for (int col = 1; col <= 5; col++) {
      int value = row * col;
      if (value < 10) std::cout << " ";  // line up the columns
      std::cout << value << " ";
    }
    std::cout << "\n";
  }
  return 0;
}

#include <fstream>
#include <iostream>
#include <string>

const std::string FILE_NAME = "notes.txt";

int main() {
  // Ask for a note.
  std::cout << "Type a note to save: ";
  std::string note;
  if (!std::getline(std::cin, note) || note.empty()) {
    std::cout << "No note typed, nothing saved.\n";
  } else {
    // std::ios::app means "add to the end" instead of wiping the file.
    std::ofstream out(FILE_NAME, std::ios::app);
    if (!out) {
      std::cout << "Couldn't open " << FILE_NAME << " for writing.\n";
      return 1;
    }
    out << note << "\n";
    std::cout << "Saved!\n";
  }  // the file closes by itself here

  // Read the file back, one line at a time.
  std::ifstream in(FILE_NAME);
  if (!in) {
    std::cout << "There's no " << FILE_NAME << " yet.\n";
    return 0;
  }

  std::cout << "\n--- Everything in " << FILE_NAME << " ---\n";
  std::string line;
  int lineNumber = 1;
  while (std::getline(in, line)) {
    std::cout << lineNumber << ": " << line << "\n";
    lineNumber++;
  }
  std::cout << "--- Total notes: " << (lineNumber - 1) << " ---\n";
  return 0;
}

#include <cmath>
#include <iostream>
#include <sstream>
#include <string>

int main() {
  std::cout << "Calculator! Type things like 7 + 5 or 9 / 2. Use + - * / % ^\n"
            << "Type q to quit.\n";

  std::string line;
  while (true) {
    std::cout << "\n> ";
    if (!std::getline(std::cin, line)) break;  // input closed
    if (line == "q" || line == "quit") break;

    // Split the line into: number, operator, number.
    std::istringstream in(line);
    double a = 0, b = 0;
    char op = 0, extra = 0;
    if (!(in >> a >> op >> b) || (in >> extra)) {
      std::cout << "I didn't get that. Try: 3 + 4\n";
      continue;
    }

    double answer = 0;
    bool ok = true;
    switch (op) {
      case '+': answer = a + b; break;
      case '-': answer = a - b; break;
      case '*': case 'x': answer = a * b; break;
      case '/':
        if (b == 0) { std::cout << "You can't divide by zero!\n"; ok = false; }
        else answer = a / b;
        break;
      case '%':
        if (b == 0) { std::cout << "You can't divide by zero!\n"; ok = false; }
        else answer = std::fmod(a, b);
        break;
      case '^': answer = std::pow(a, b); break;
      default:
        std::cout << "I don't know the '" << op << "' sign. Use + - * / % ^\n";
        ok = false;
    }

    if (ok) std::cout << "= " << answer << "\n";
  }

  std::cout << "Bye!\n";
  return 0;
}

#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

// Print every item in a vector of strings.
void printAll(const std::vector<std::string> &items) {
  std::cout << "[";
  for (std::size_t i = 0; i < items.size(); i++) {
    std::cout << items[i];
    if (i + 1 < items.size()) std::cout << ", ";
  }
  std::cout << "]  (size " << items.size() << ")\n";
}

int main() {
  // A vector is a list that can grow and shrink.
  std::vector<std::string> inventory = {"sword", "shield"};
  printAll(inventory);

  // Add to the end.
  inventory.push_back("potion");
  inventory.push_back("map");
  std::cout << "After adding: ";
  printAll(inventory);

  // Read and change an item by its position (starts at 0!).
  std::cout << "First item: " << inventory[0] << "\n";
  inventory[1] = "golden shield";
  std::cout << "After upgrade: ";
  printAll(inventory);

  // Find an item.
  auto spot = std::find(inventory.begin(), inventory.end(), "potion");
  if (spot != inventory.end()) {
    std::cout << "Found potion at position " << (spot - inventory.begin()) << "\n";
    inventory.erase(spot);  // use it up
  }
  std::cout << "After using potion: ";
  printAll(inventory);

  // Remove the last item.
  inventory.pop_back();
  std::cout << "After dropping last item: ";
  printAll(inventory);

  // A vector of numbers, plus a "for each" loop to add them up.
  std::vector<int> scores = {40, 75, 90, 15};
  int total = 0;
  for (int score : scores) total += score;
  std::cout << "Total score: " << total << "\n";

  // Sort the numbers from small to big.
  std::sort(scores.begin(), scores.end());
  std::cout << "Sorted scores:";
  for (int score : scores) std::cout << " " << score;
  std::cout << "\n";

  // Empty it out.
  inventory.clear();
  std::cout << "Inventory empty? " << (inventory.empty() ? "yes" : "no") << "\n";
  return 0;
}

#include <cctype>
#include <iostream>
#include <random>
#include <string>
#include <vector>

int main() {
  const std::vector<std::string> words = {"robot", "planet", "castle", "dragon",
                                          "rocket", "pizza", "jungle", "laptop"};

  std::random_device seed;
  std::mt19937 rng(seed());
  std::uniform_int_distribution<std::size_t> pick(0, words.size() - 1);

  const std::string secret = words[pick(rng)];
  std::string shown(secret.size(), '_');  // what the player sees, like "_ _ _"
  std::string guessed;                     // letters tried so far
  int lives = 6;

  std::cout << "Hangman! Guess the word one letter at a time.\n";

  while (lives > 0 && shown != secret) {
    std::cout << "\nWord: ";
    for (char c : shown) std::cout << c << ' ';
    std::cout << "\nLives: " << lives << "   Tried: " << guessed << "\nLetter: ";

    std::string line;
    if (!std::getline(std::cin, line)) return 0;  // input closed

    // Only accept exactly one letter.
    if (line.size() != 1 || !std::isalpha(static_cast<unsigned char>(line[0]))) {
      std::cout << "Please type one letter.\n";
      continue;
    }
    char letter = static_cast<char>(std::tolower(static_cast<unsigned char>(line[0])));

    if (guessed.find(letter) != std::string::npos) {
      std::cout << "You already tried '" << letter << "'.\n";
      continue;
    }
    guessed += letter;

    // Reveal every spot where the letter appears.
    bool found = false;
    for (std::size_t i = 0; i < secret.size(); i++) {
      if (secret[i] == letter) {
        shown[i] = letter;
        found = true;
      }
    }

    if (found) {
      std::cout << "Nice! '" << letter << "' is in the word.\n";
    } else {
      lives--;
      std::cout << "Nope, no '" << letter << "'.\n";
    }
  }

  if (shown == secret) {
    std::cout << "\nYou won! The word was " << secret << ".\n";
  } else {
    std::cout << "\nOut of lives! The word was " << secret << ".\n";
  }
  return 0;
}

#include <iostream>
#include <random>
#include <sstream>
#include <string>

// Ask for a whole number. Keeps asking if you type letters.
// Returns false if the input is closed (so we never loop forever).
bool readNumber(const std::string &prompt, int &number) {
  std::string line;
  while (true) {
    std::cout << prompt;
    if (!std::getline(std::cin, line)) return false;
    std::istringstream in(line);
    char extra;
    if (in >> number && !(in >> extra)) return true;
    std::cout << "That's not a number. Try again!\n";
  }
}

int main() {
  // Set up a good random number maker.
  std::random_device seed;
  std::mt19937 rng(seed());
  std::uniform_int_distribution<int> pick(1, 100);

  bool playAgain = true;
  while (playAgain) {
    int secret = pick(rng);
    int tries = 0;
    int guess = 0;

    std::cout << "\nI'm thinking of a number from 1 to 100...\n";
    while (guess != secret) {
      if (!readNumber("Your guess: ", guess)) return 0;
      if (guess < 1 || guess > 100) {
        std::cout << "Pick between 1 and 100.\n";
        continue;
      }
      tries++;
      if (guess < secret) std::cout << "Higher!\n";
      else if (guess > secret) std::cout << "Lower!\n";
    }
    std::cout << "You got it in " << tries << " tries!\n";

    // Ask to play again.
    std::cout << "Play again? (y/n): ";
    std::string answer;
    if (!std::getline(std::cin, answer)) return 0;
    playAgain = !answer.empty() && (answer[0] == 'y' || answer[0] == 'Y');
  }

  std::cout << "Thanks for playing!\n";
  return 0;
}

#include <cctype>
#include <iostream>
#include <random>
#include <string>

const std::string NAMES[3] = {"rock", "paper", "scissors"};

// Turn what you typed into 0, 1 or 2. Returns -1 if it's not a move.
int toMove(const std::string &text) {
  if (text == "r" || text == "rock") return 0;
  if (text == "p" || text == "paper") return 1;
  if (text == "s" || text == "scissors") return 2;
  return -1;
}

int main() {
  std::random_device seed;
  std::mt19937 rng(seed());
  std::uniform_int_distribution<int> pick(0, 2);

  int wins = 0, losses = 0, ties = 0;
  std::cout << "Rock Paper Scissors! Type r, p or s (or q to quit).\n";

  while (true) {
    std::cout << "\nYour move: ";
    std::string input;
    if (!std::getline(std::cin, input)) break;  // input closed
    for (char &c : input) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    if (input == "q" || input == "quit") break;

    int you = toMove(input);
    if (you < 0) {
      std::cout << "Hmm, type r, p or s.\n";
      continue;
    }

    int computer = pick(rng);
    std::cout << "You: " << NAMES[you] << "  Computer: " << NAMES[computer] << "\n";

    // Each move beats the one just before it: paper > rock, scissors > paper, rock > scissors.
    if (you == computer) {
      std::cout << "Tie!\n";
      ties++;
    } else if ((you + 2) % 3 == computer) {
      std::cout << "You win!\n";
      wins++;
    } else {
      std::cout << "Computer wins!\n";
      losses++;
    }
    std::cout << "Score - You: " << wins << "  Computer: " << losses << "  Ties: " << ties << "\n";
  }

  std::cout << "\nFinal score - You: " << wins << "  Computer: " << losses
            << "  Ties: " << ties << "\nThanks for playing!\n";
  return 0;
}

#include <cctype>
