except ValueError as error:
    print("Oops:", error)

account.show()

def binary_search(items, target):
    low, high = 0, len(items) - 1
    steps = 0
    while low <= high:
        steps += 1
        middle = (low + high) // 2
        print(f"  step {steps}: checking position {middle} (value {items[middle]})")
        if items[middle] == target:
            return middle, steps
        if items[middle] < target:
            low = middle + 1   # target is in the right half
        else:
            high = middle - 1  # target is in the left half
    return -1, steps


numbers = list(range(0, 1000, 3))  # 0, 3, 6, ... sorted!
for target in [588, 1, 999]:
    print(f"Looking for {target} in {len(numbers)} numbers:")
    position, steps = binary_search(numbers, target)
    if position == -1:
        print(f"  Not found after {steps} steps.\n")
    else:
        print(f"  Found at position {position} in just {steps} steps!\n")

class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None


def insert(node, value):
    if node is None:
        return TreeNode(value)
    if value < node.value:
        node.left = insert(node.left, value)
    else:
        node.right = insert(node.right, value)
    return node


def contains(node, value):
    while node is not None:
        if value == node.value:
            return True
        node = node.left if value < node.value else node.right
    return False


def in_order(node, out):
    """Left, me, right: this visits the values in sorted order."""
    if node:
        in_order(node.left, out)
        out.append(node.value)
        in_order(node.right, out)
    return out


def height(node):
    if node is None:
        return 0
    return 1 + max(height(node.left), height(node.right))


def show(node, depth=0):
    """Print the tree sideways (right side on top)."""
    if node:
        show(node.right, depth + 1)
        print("    " * depth + str(node.value))
        show(node.left, depth + 1)


root = None
for n in [50, 30, 70, 20, 40, 60, 80, 35]:
    root = insert(root, n)

show(root)
print("In order:", in_order(root, []))
print("Height:", height(root))
print("Has 60?", contains(root, 60), " Has 65?", contains(root, 65))

from dataclasses import dataclass, field


@dataclass
class Item:
    name: str
    price: int
    rarity: str = "common"   # a default value


@dataclass
class Inventory:
