    print(n)
    countdown(n - 1)


def sum_of_digits(n):
    if n < 10:
        return n
    return n % 10 + sum_of_digits(n // 10)


def reverse(text):
    if text == "":
        return ""
    return reverse(text[1:]) + text[0]


